BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."TimetableWorkflowMaster" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "Code" varchar(60) NOT NULL,
    "Name" varchar(160) NOT NULL,
    "Description" varchar(500),
    "CampusId" bigint,
    "ClassSectionId" bigint,
    "AllowTeacherDraftProposal" boolean NOT NULL DEFAULT false,
    "AutoPublishAfterFinalApproval" boolean NOT NULL DEFAULT true,
    "IsDefault" boolean NOT NULL DEFAULT false,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp without time zone
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_TimetableWorkflow_Institution_Code" ON skolenza."TimetableWorkflowMaster" ("InstitutionId", lower("Code")) WHERE NOT "IsSoftDeleted";
CREATE UNIQUE INDEX IF NOT EXISTS "UX_TimetableWorkflow_Institution_Default" ON skolenza."TimetableWorkflowMaster" ("InstitutionId") WHERE "IsDefault" AND "IsActive" AND NOT "IsSoftDeleted";

CREATE TABLE IF NOT EXISTS skolenza."TimetableWorkflowStep" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "TimetableWorkflowMasterId" bigint NOT NULL REFERENCES skolenza."TimetableWorkflowMaster"("Id") ON DELETE CASCADE,
    "Sequence" smallint NOT NULL,
    "ApproverTypeCode" varchar(40) NOT NULL,
    "AccessRoleId" integer,
    "StaffPositionMasterId" integer,
    "StaffMemberId" bigint,
    "IsActive" boolean NOT NULL DEFAULT true,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "CK_TimetableWorkflowStep_ApproverType" CHECK ("ApproverTypeCode" IN ('MANAGER','ACCESS_ROLE','POSITION','STAFF_MEMBER')),
    CONSTRAINT "UQ_TimetableWorkflowStep_Sequence" UNIQUE ("TimetableWorkflowMasterId", "Sequence")
);

ALTER TABLE skolenza."TimetableEntry" ADD COLUMN IF NOT EXISTS "TimetableWorkflowMasterId" bigint;
ALTER TABLE skolenza."TimetableEntry" ADD COLUMN IF NOT EXISTS "ParentTimetableEntryId" bigint;
ALTER TABLE skolenza."TimetableEntry" ADD COLUMN IF NOT EXISTS "RevisionNumber" integer NOT NULL DEFAULT 1;
ALTER TABLE skolenza."TimetableEntry" ADD COLUMN IF NOT EXISTS "StatusCode" varchar(40) NOT NULL DEFAULT 'DRAFT';
ALTER TABLE skolenza."TimetableEntry" ADD COLUMN IF NOT EXISTS "CurrentApprovalSequence" smallint NOT NULL DEFAULT 0;
ALTER TABLE skolenza."TimetableEntry" ADD COLUMN IF NOT EXISTS "SubmittedDateTime" timestamp without time zone;
ALTER TABLE skolenza."TimetableEntry" ADD COLUMN IF NOT EXISTS "ApprovedDateTime" timestamp without time zone;
ALTER TABLE skolenza."TimetableEntry" ADD COLUMN IF NOT EXISTS "PublishedDateTime" timestamp without time zone;
ALTER TABLE skolenza."TimetableEntry" ADD COLUMN IF NOT EXISTS "RejectedDateTime" timestamp without time zone;
ALTER TABLE skolenza."TimetableEntry" ADD COLUMN IF NOT EXISTS "ReviewRemark" varchar(500);
UPDATE skolenza."TimetableEntry" SET "StatusCode"='PUBLISHED', "PublishedDateTime"=COALESCE("PublishedDateTime","AddedDateTime") WHERE "StatusCode"='DRAFT' AND "TimetableWorkflowMasterId" IS NULL;

CREATE TABLE IF NOT EXISTS skolenza."TimetableApprovalHistory" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "TimetableEntryId" bigint NOT NULL REFERENCES skolenza."TimetableEntry"("Id") ON DELETE CASCADE,
    "Sequence" smallint NOT NULL,
    "ActionByStaffMemberId" bigint NOT NULL,
    "ActionCode" varchar(40) NOT NULL,
    "Remark" varchar(500),
    "ActionDateTime" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "IX_TimetableApprovalHistory_Entry" ON skolenza."TimetableApprovalHistory" ("TimetableEntryId", "ActionDateTime");
CREATE INDEX IF NOT EXISTS "IX_TimetableEntry_WorkflowStatus" ON skolenza."TimetableEntry" ("InstitutionId", "StatusCode", "CurrentApprovalSequence");

COMMIT;
